    "filters/CleanPolyData": {
      "short": "Merge coincident points.",
      "long": "Merge coincident points if they do not meet a feature edge criteria.",
      "description": "The Clean filter takes polygonal data as input and generates polygonal data as output. This filter can merge duplicate points, remove unused points, and transform degenerate cells into their appropriate forms (e.g., a triangle is converted into a line if two of its points are merged).",
