    "filters/GaussianSplatter": {
      "short": "Point to voxel splatter.",
      "long": "Splat points into a volume with an elliptical, Gaussian distribution.",
      "description": "vtkGaussianSplatter is a filter that injects input points into a structured points (volume) dataset. As each point is injected, it \"splats\" or distributes values to nearby voxels. Data is distributed using an elliptical, Gaussian distribution function. The distribution function is modified using scalar values (expands distribution) or normals (creates ellipsoidal distribution rather than spherical). Warning: results may be incorrect in parallel as points can't splat into other processor's cells.",
      "selection": "Point to voxel splatter.",
      "basis": "installed native documentation",
      "properties": {
        "Accumulation Mode": {
          "short": null,
          "long": null,
          "description": "Specify the scalar accumulation mode. This mode expresses how scalar values are combined when splats are overlapped. The Max mode acts like a set union operation and is the most commonly used; the Min mode acts like a set intersection, and the sum is just weird.",
          "label": "Splat Accumulation Mode",
          "pythonName": "SplatAccumulationMode"
        },
        "CapValue": {
          "short": null,
          "long": null,
          "description": "Specify the cap value to use. (This instance variable only has effect if the ivar Capping is on.)",
          "label": "Fill Value",
          "pythonName": "FillValue"
        },
        "Capping": {
          "short": null,
          "long": null,
          "description": "Turn on/off the capping of the outer boundary of the volume to a specified cap value. This can be used to close surfaces (after isosurfacing) and create other effects.",
          "label": "Fill Volume Boundary",
          "pythonName": "FillVolumeBoundary"
        },
        "Eccentricity": {
          "short": null,
          "long": null,
          "description": "Control the shape of elliptical splatting. Eccentricity is the ratio of the major axis (aligned along normal) to the minor (axes) aligned along other two axes. So Eccentricity gt 1 creates needles with the long axis in the direction of the normal; Eccentricity lt 1 creates pancakes perpendicular to the normal vector.",
          "label": "Ellipitical Eccentricity",
          "pythonName": "EllipiticalEccentricity"
        },
        "ExponentFactor": {
          "short": null,
          "long": null,
          "description": "Set / get the sharpness of decay of the splats. This is the exponent constant in the Gaussian equation. Normally this is a negative value.",
          "label": "Gaussian Exponent Factor",
          "pythonName": "GaussianExponentFactor"
        },
        "Input": {
          "short": null,
          "long": null,
          "description": "This property specifies the input to the filter.",
          "label": "Input",
          "pythonName": "Input"
        },
        "ModelBounds": {
          "short": null,
          "long": null,
          "description": "Set / get the (xmin,xmax, ymin,ymax, zmin,zmax) bounding box in which the sampling is performed. If any of the (min,max) bounds values are min >= max, then the bounds will be computed automatically from the input data. Otherwise, the user-specified bounds will be used.",
          "label": "Extent to Resample",
          "pythonName": "ExtenttoResample"
        },
        "NormalWarping": {
          "short": null,
          "long": null,
          "description": "Turn on/off the generation of elliptical splats. If normal warping is on, then the input normals affect the distribution of the splat. This boolean is used in combination with the Eccentricity ivar.",
          "label": "Elliptical Splats",
          "pythonName": "EllipticalSplats"
        },
        "NullValue": {
          "short": null,
          "long": null,
          "description": "Set the Null value for output points not receiving a contribution from the input points. (This is the initial value of the voxel samples.)",
          "label": "Empty Cell Value",
          "pythonName": "EmptyCellValue"
        },
        "Radius": {
          "short": null,
          "long": null,
          "description": "Set / get the radius of propagation of the splat. This value is expressed as a percentage of the length of the longest side of the sampling volume. Smaller numbers greatly reduce execution time.",
          "label": "Gaussian Splat Radius",
          "pythonName": "GaussianSplatRadius"
        },
        "SampleDimensions": {
          "short": null,
          "long": null,
          "description": "Set / get the dimensions of the sampling structured point set. Higher values produce better results but are much slower.",
          "label": "Resampling Grid",
          "pythonName": "ResamplingGrid"
        },
        "ScalarWarping": {
          "short": null,
          "long": null,
          "description": "Turn on/off the scaling of splats by scalar value.",
          "label": "Scale Splats",
          "pythonName": "ScaleSplats"
        },
        "ScaleFactor": {
          "short": null,
          "long": null,
          "description": "Multiply Gaussian splat distribution by this value. If ScalarWarping is on, then the Scalar value will be multiplied by the ScaleFactor times the Gaussian function.",
          "label": "Scale Factor",
          "pythonName": "ScaleFactor"
        },
        "SelectInputScalars": {
          "short": null,
          "long": null,
          "description": "Choose a scalar array to splat into the output cells. If ignore arrays is chosen, point density will be counted instead.",
          "label": "Resample Field",
          "pythonName": "ResampleField"
        }
      }
    },
