    "filters/PolyDataNormals": {
      "short": "Produce surface point normals.",
      "long": "This filter will produce surface normals used for smooth shading. Splitting is used to avoid smoothing across feature edges.",
      "description": "This filter generates surface normals at the points of the input polygonal dataset to provide smooth shading of the dataset. The resulting dataset is also polygonal. The filter works by calculating a normal vector for each polygon in the dataset and then averaging the normals at the shared points.",
      "selection": "Produce surface point normals.",
      "basis": "installed native documentation",
      "properties": {
        "ComputeCellNormals": {
          "short": null,
          "long": null,
          "description": "This filter computes the normals at the points in the data set. In the process of doing this it computes polygon normals too. If you want these normals to be passed to the output of this filter, set the value of this property to 1.",
          "label": "Compute Cell Normals",
          "pythonName": "ComputeCellNormals"
        },
        "Consistency": {
          "short": null,
          "long": null,
          "description": "The value of this property controls whether consistent polygon ordering is enforced. Generally the normals for a data set should either all point inward or all point outward. If the value of this property is 1, then this filter will reorder the points of cells that whose normal vectors are oriented the opposite direction from the rest of those in the data set.",
          "label": "Consistency",
          "pythonName": "Consistency"
        },
        "FeatureAngle": {
          "short": null,
          "long": null,
          "description": "The value of this property defines a feature edge. If the surface normal between two adjacent triangles is at least as large as this Feature Angle, a feature edge exists. If Splitting is on, points are duplicated along these feature edges. (See the Splitting property.)",
          "label": "Feature Angle",
          "pythonName": "FeatureAngle"
        },
        "FlipNormals": {
          "short": null,
          "long": null,
          "description": "If the value of this property is 1, this filter will reverse the normal direction (and reorder the points accordingly) for all polygons in the data set; this changes front-facing polygons to back-facing ones, and vice versa. You might want to do this if your viewing position will be inside the data set instead of outside of it.",
          "label": "Flip Normals",
          "pythonName": "FlipNormals"
        },
        "Input": {
          "short": null,
          "long": null,
          "description": "This property specifies the input to the Normals Generation filter.",
          "label": "Input",
          "pythonName": "Input"
        },
        "NonManifoldTraversal": {
          "short": null,
          "long": null,
          "description": "Turn on/off traversal across non-manifold edges. Not traversing non-manifold edges will prevent problems where the consistency of polygonal ordering is corrupted due to topological loops.",
          "label": "Non-Manifold Traversal",
          "pythonName": "NonManifoldTraversal"
        },
        "PieceInvariant": {
          "short": null,
          "long": null,
          "description": "Turn this option to to produce the same results regardless of the number of processors used (i.e., avoid seams along processor boundaries). Turn this off if you do want to process ghost levels and do not mind seams.",
          "label": "Piece Invariant",
          "pythonName": "PieceInvariant"
        },
        "Splitting": {
          "short": null,
          "long": null,
          "description": "This property controls the splitting of sharp edges. If sharp edges are split (property value = 1), then points are duplicated along these edges, and separate normals are computed for both sets of points to give crisp (rendered) surface definition.",
          "label": "Splitting",
          "pythonName": "Splitting"
        }
      }
    },
