    "filters/Glyph": {
      "short": "Generate glyphs that represent attributes in the input data set.",
      "long": "This filter produces a glyph at points or cell centers in an input data set. The glyphs can be oriented and scaled by point or cell attributes of the input dataset.",
      "description": "The Glyph filter generates a glyph (i.e., an arrow, cone, cube, cylinder, line, sphere, or 2D glyph) at each point or cell in the input dataset. The glyphs can be oriented and scaled by the input scalar and vector arrays. If the arrays are point-centered, glyphs are placed at points in the input dataset. If the arrays are cell-centered, glyphs are placed at the center of cells in the input dataset. A transform that applies to the glyph source can be modified to change the shape of the glyph. This filter operates on any type of data set. Its output is a polygonal dataset. To use this filter, select the **Orientation Array** to orient the glyphs and the **Scale Array** to control glyph scaling if desired - each array can be set to 'No array' if orientation or scaling is not desired. When scaling by a 3-element vector array, the **Vector Scale Mode** can be set to either 'Scale by Magnitude', which scales glyphs according to the vector magnitude, or 'Scale by Components', which treats each component as a separate scaling factor in the corresponding dimension, i.e., the first component is the scaling factor in the x-dimension, the second component scales the y-dimension, and the third component scales the z-dimension. An overall constant **Scale Factor** is applied following the scaling controlled by other properties of this filter. The **Glyph Mode** property controls which points in the input dataset are selected for glyphing since in most cases, glyphing all points in the input dataset can be both performance impeding as well as visually cluttered.",
      "selection": "Generate glyphs that represent attributes in the input data set.",
      "basis": "installed native documentation",
      "properties": {
        "ComponentSelection": {
          "short": null,
          "long": null,
          "description": "Specifies array component to use. Fixed at 4 to ensure the ArrayRangeDomain is set to the vector magnitude for up to 3-component arrays.",
          "label": "Component Selection",
          "pythonName": "ComponentSelection"
        },
        "GlyphMode": {
          "short": null,
          "long": null,
          "description": "This property indicates the mode that will be used to generate glyphs from the dataset.",
          "label": "Glyph Mode",
          "pythonName": "GlyphMode"
        },
        "GlyphTransform": {
          "short": null,
          "long": null,
          "description": "The values in this property allow you to specify the transform (translation, rotation, and scaling) to apply to the glyph source.",
          "label": "Glyph Transform",
          "pythonName": "GlyphTransform"
        },
        "Input": {
          "short": null,
          "long": null,
          "description": "This property specifies the input to this filter. This is the dataset from which the locations are selected to be glyphed.",
          "label": "Input",
          "pythonName": "Input"
        },
        "MaximumNumberOfSamplePoints": {
          "short": null,
          "long": null,
          "description": "This property specifies the maximum number of sample points to use when sampling the space when Uniform Spatial Distribution is used.",
          "label": "Maximum Number Of Sample Points",
          "pythonName": "MaximumNumberOfSamplePoints"
        },
        "OrientationArray": {
          "short": null,
          "long": null,
          "description": "Select the input array to use for orienting the glyphs.",
          "label": "Orientation Array",
          "pythonName": "OrientationArray"
        },
        "ScaleArray": {
          "short": null,
          "long": null,
          "description": "Select the input array to be used for scaling the glyphs. If the scale array is a vector array, you can control how the glyphs are scaled with the **Vector Scale Mode** property.",
          "label": "Scale Array",
          "pythonName": "ScaleArray"
        },
        "ScaleFactor": {
          "short": null,
          "long": null,
          "description": "Specify the constant multiplier to use to scale the glyphs.",
          "label": "Scale Factor",
          "pythonName": "ScaleFactor"
        },
        "Seed": {
          "short": null,
          "long": null,
          "description": "This property specifies the seed that will be used for generating a uniform distribution of glyph points when a Uniform Spatial Distribution is used.",
          "label": "Seed",
          "pythonName": "Seed"
        },
        "Source": {
          "short": null,
          "long": null,
          "description": "This property determines which type of glyph will be placed at the points in the input dataset.",
          "label": "Glyph Type",
          "pythonName": "GlyphType"
        },
        "Stride": {
          "short": null,
          "long": null,
          "description": "This property specifies the stride that will be used when glyphing by Every Nth Point.",
          "label": "Stride",
          "pythonName": "Stride"
        },
        "VectorScaleMode": {
          "short": null,
          "long": null,
          "description": "Select the mode when the scaling array is a vector. **Scale by Magnitude** scales the glyph by the vector magnitude. **Scale by Components** scales glyphs by each vector component in the dimension that component represents, e.g., the x-direction is scaled by component 0, the y-direction is scaled by component 1, and so on.",
          "label": "Vector Scale Mode",
          "pythonName": "VectorScaleMode"
        }
      }
    },
