        },
        "Offset": {
          "short": null,
          "long": null,
          "description": "The value of this property indicates the starting point id in the ordered list of input points from which to start masking.",
          "label": "Offset",
          "pythonName": "Offset"
        },
        "OnRatio": {
          "short": null,
          "long": null,
          "description": "The value of this property specifies that every OnStride-th points will be retained in the output when not using Random (the skip or stride size for point ids). (For example, if the on ratio is 3, then the output will contain every 3rd point, up to the the maximum number of points.)",
          "label": "On Ratio",
          "pythonName": "OnRatio"
        },
        "ProportionalMaximumNumberOfPoints": {
          "short": null,
          "long": null,
          "description": "When this is off, the maximum number of points is taken per processor when running in parallel (total number of points = number of processors * maximum number of points). When this is on, the maximum number of points is proportionally distributed across processors depending on the number of points per processor (\"total number of points\" is the same as \"maximum number of points\" maximum number of points per processor = number of points on a processor * maximum number of points / total number of points across all processors ).",
          "label": "Proportionally Distribute Maximum Number Of Points",
          "pythonName": "ProportionallyDistributeMaximumNumberOfPoints"
        },
        "RandomMode": {
          "short": null,
          "long": null,
          "description": "If the value of this property is set to true, then the points in the output will be randomly selected from the input in various ways set by Random Mode; otherwise this filter will subsample point ids regularly.",
          "label": "Random Sampling",
          "pythonName": "RandomSampling"
        },
        "RandomModeType": {
          "short": null,
          "long": null,
          "description": "Randomized Id Strides picks points with random id increments starting at Offset (the output probably isn't a statistically random sample). Random Sampling generates a statistically random sample of the input, ignoring Offset (fast - O(sample size)). Spatially Stratified Random Sampling is a variant of random sampling that splits the points into equal sized spatial strata before randomly sampling (slow - O(N log N)). The Uniform Spatial Distribution (Bound based) samples points using random poisitions inside the bounds of the data set and a point locator. The Uniform Spatial Distribution (Surface Sampling) samples points randomly via an inverse transform on surface area of each cell (3D cells are ignored). The Uniform Spatial Distribution (Volume Sampling) samples points randomly sampled via an inverse transform on volume area of each cell (2D cells are ignored).",
          "label": "Random Sampling Mode",
          "pythonName": "RandomSamplingMode"
        },
        "SingleVertexPerCell": {
          "short": null,
          "long": null,
          "description": "Tell filter to only generate one vertex per cell instead of multiple vertices in one cell.",
          "label": "Single Vertex Per Cell",
          "pythonName": "SingleVertexPerCell"
        }
      }
    },
    "filters/MaterialInterfaceFilter": {
      "short": "The Material Interface filter finds volumes in the input data containing material above a certain material fraction.",
      "long": "The Material Interface filter finds volumes in the input data containing material above a certain material fraction.",
      "description": "The Material Interface filter finds voxels inside of which a material fraction (or normalized amount of material) is higher than a given threshold. As these voxels are identified surfaces enclosing adjacent voxels above the threshold are generated. The resulting volume and its surface are what we call a fragment. The filter has the ability to compute various volumetric attributes such as fragment volume, mass, center of mass as well as volume and mass weighted averages for any of the fields present. Any field selected for such computation will be also be copied into the fragment surface's point data for visualization. The filter also has the ability to generate Oriented Bounding Boxes (OBB) for each fragment. The data generated by the filter is organized in three outputs. The \"geometry\" output, containing the fragment surfaces. The \"statistics\" output, containing a point set of the centers of mass. The \"obb representation\" output, containing OBB representations (poly data). All computed attributes are copied into the statistics and geometry output. The obb representation output is used for validation and debugging purposes and is turned off by default. To measure the size of craters, the filter can invert a volume fraction and clip the volume fraction with a sphere and/or a plane.",
      "selection": "The Material Interface filter finds volumes in the input data containing material above a certain material fraction.",
      "basis": "installed native documentation",
      "properties": {
        "ClipFunction": {
          "short": null,
          "long": null,
          "description": "This property sets the type of clip geometry, and associated parameters.",
          "label": "Clip Type",
          "pythonName": "ClipType"
        },
        "ComputeOBB": {
          "short": null,
          "long": null,
          "description": "Compute Object Oriented Bounding boxes (OBB). When active the result of this computation is copied into the statistics output. In the case that the filter is built in its validation mode, the OBB's are rendered.",
          "label": "Compute OBB",
          "pythonName": "ComputeOBB"
        },
        "Input": {
          "short": null,
          "long": null,
          "description": "Input to the filter can be a hierarchical box data set containing image data or a multiblock of rectilinear grids.",
          "label": "Input",
          "pythonName": "Input"
        },
        "InvertVolumeFraction": {
          "short": null,
          "long": null,
          "description": "Inverting the volume fraction generates the negative of the material. It is useful for analyzing craters.",
          "label": "Invert Volume Fraction",
          "pythonName": "InvertVolumeFraction"
        },
        "MaterialFractionThreshold": {
          "short": null,
          "long": null,
          "description": "Material fraction is defined as normalized amount of material per voxel. Any voxel in the input data set with a material fraction greater than this value is included in the output data set.",
          "label": "Material Fraction Threshold",
          "pythonName": "MaterialFractionThreshold"
        },
        "OutputBaseName": {
          "short": null,
          "long": null,
          "description": "This property specifies the base including path of where to write the statistics and geometry output text files. It follows the pattern \"/path/to/folder/and/file\" here file has no extension, as the filter will generate a unique extension.",
          "label": "Output Base Name",
          "pythonName": "OutputBaseName"
        },
        "SelectMassArray": {
          "short": null,
          "long": null,
          "description": "Mass arrays are paired with material fraction arrays. This means that the first selected material fraction array is paired with the first selected mass array, and so on sequentially. As the filter identifies voxels meeting the minimum material fraction threshold, these voxel's mass will be used in fragment center of mass and mass calculation. A warning is generated if no mass array is selected for an individual material fraction array. However, in that case the filter will run without issue because the statistics output can be generated using fragments' centers computed from axis aligned bounding boxes.",
          "label": "Select Mass Arrays",
          "pythonName": "SelectMassArrays"
        },
        "SelectMassWtdAvgArray": {
