    "filters/Median": {
      "short": "Compute median values in a given neighborhood.",
      "long": "Compute the median scalar values in a specified neighborhood for image/volume datasets.",
      "description": "The Median filter operates on uniform rectilinear (image or volume) data and produces uniform rectilinear output. It replaces the scalar value at each pixel / voxel with the median scalar value in the specified surrounding neighborhood. Since the median operation removes outliers, this filter is useful for removing high-intensity, low-probability noise (shot noise).",
      "selection": "Compute median values in a given neighborhood.",
      "basis": "installed native documentation",
      "properties": {
        "Input": {
          "short": null,
          "long": null,
