    "sources/netCDFReader": {
      "short": "Read regular arrays from NetCDF files.",
      "long": "Reads regular arrays from NetCDF files. Will also read any topological information specified by the COARDS and CF conventions.",
      "description": "Reads arrays from NetCDF files into structured VTK data sets. In the absence of any other information, the files will be read as image data. This reader will also look for meta information specified by the CF convention that specify things like topology and time. This information can cause the output to be a nonuniform rectilinear grid or curvilinear (structured) grid. Details on the CF convention can be found at http://cf-pcmdi.llnl.gov/. It should be noted that the CF convention is a superset of the COARDS convention, so COARDS conventions will also be recognized.",
      "selection": "Read regular arrays from NetCDF files.",
      "basis": "installed native documentation",
      "properties": {
        "FileName": {
          "short": null,
          "long": null,
          "description": "The name of the files to load.",
          "label": "File Name",
          "pythonName": "FileName"
        },
        "TimestepValues": {
          "short": null,
          "long": null,
          "description": "This magic property sends time information to the animation panel. ParaView will then automatically set up the animation to visit the time steps defined in the file.",
          "label": "Timestep Values",
          "pythonName": "TimestepValues"
        },
        "DimensionInfo": {
          "short": null,
          "long": null,
          "description": null,
          "label": "Dimension Info",
          "pythonName": "DimensionInfo"
        },
        "Dimensions": {
          "short": null,
          "long": null,
          "description": "Load the grid with the given dimensions. Any arrays that conform to these dimensions will be loaded.",
          "label": "Dimensions",
          "pythonName": "Dimensions"
        },
        "OutputType": {
          "short": null,
          "long": null,
          "description": "Specifies the type of data that the reader creates. If Automatic, the reader will use the most appropriate grid type for the data read. Note that not all grid types support all data. A warning is issued if a mismatch occurs.",
          "label": "Output Type",
          "pythonName": "OutputType"
        },
        "ReplaceFillValueWithNan": {
          "short": null,
          "long": null,
          "description": "If on, any float or double variable read that has a _FillValue attribute will have that fill value replaced with a not-a-number (NaN) value. The advantage of setting these to NaN values is that, if implemented properly by the system and careful math operations are used, they can implicitly be ignored by calculations like finding the range of the values. That said, this option should be used with caution as VTK does not fully support NaN values and therefore odd calculations may occur.",
          "label": "Replace Fill Value With Nan",
          "pythonName": "ReplaceFillValueWithNan"
        },
        "SphericalCoordinates": {
          "short": null,
          "long": null,
          "description": "If on, then data with latitude/longitude dimensions will be read in as curvilinear data shaped like spherical coordinates. If false, then the data will always be read in Cartesian coordinates.",
          "label": "Spherical Coordinates",
          "pythonName": "SphericalCoordinates"
        },
        "VariableArrayInfo": {
          "short": null,
          "long": null,
          "description": null,
          "label": "Variable Array Info",
          "pythonName": "VariableArrayInfo"
        },
        "VariableDimensionInfo": {
          "short": null,
          "long": null,
          "description": null,
          "label": "Variable Dimension Info",
          "pythonName": "VariableDimensionInfo"
        },
        "VerticalBias": {
          "short": null,
          "long": null,
          "description": "The bias of the vertical component of spherical coordinates. It is common to write the vertical component with respect to something other than the center of the sphere (for example, the surface). In this case, it might be necessary to scale and/or bias the vertical height. The height will become height*scale + bias. Keep in mind that if the positive attribute of the vertical dimension is down, then the height is negated. The scaling will be adjusted if it results in invalid (negative) vertical values.",
          "label": "Vertical Bias",
          "pythonName": "VerticalBias"
        },
        "VerticalScale": {
          "short": null,
          "long": null,
          "description": "The scale of the vertical component of spherical coordinates. It is common to write the vertical component with respect to something other than the center of the sphere (for example, the surface). In this case, it might be necessary to scale and/or bias the vertical height. The height will become height*scale + bias. Keep in mind that if the positive attribute of the vertical dimension is down, then the height is negated. The scaling will be adjusted if it results in invalid (negative) vertical values.",
          "label": "Vertical Scale",
          "pythonName": "VerticalScale"
        }
      }
    },
