    "filters/ParticlePath": {
      "short": "Trace Particle Paths through time in a vector field.",
      "long": "Trace Particle Paths through time in a vector field.",
      "description": "The Particle Trace filter generates pathlines in a vector field from a collection of seed points. The vector field used is selected from the Vectors menu, so the input data set is required to have point-centered vectors. The Seed portion of the interface allows you to select whether the seed points for this integration lie in a point cloud or along a line. Depending on which is selected, the appropriate 3D widget (point or line widget) is displayed along with traditional user interface controls for positioning the point cloud or line within the data set. Instructions for using the 3D widgets and the corresponding manual controls can be found in section 7.4. This filter operates on any type of data set, provided it has point-centered vectors. The output is polygonal data containing polylines. This filter is available on the Toolbar.",
      "selection": "Trace Particle Paths through time in a vector field.",
      "basis": "installed native documentation",
      "properties": {
        "ComputeVorticity": {
          "short": null,
          "long": null,
          "description": "Compute vorticity and angular rotation of particles as they progress",
          "label": "Compute Vorticity",
          "pythonName": "ComputeVorticity"
        },
        "ForceReinjectionEveryNSteps": {
          "short": null,
          "long": null,
          "description": "When animating particles, it is nice to inject new ones every Nth step to produce a continuous flow. Setting ForceReinjectionEveryNSteps to a non zero value will cause the particle source to reinject particles every Nth step even if it is otherwise unchanged. Note that if the particle source is also animated, this flag will be redundant as the particles will be reinjected whenever the source changes anyway.",
          "label": "Force Reinjection Every N Steps",
          "pythonName": "ForceReinjectionEveryNSteps"
        },
        "Input": {
          "short": null,
          "long": null,
          "description": "Specify which is the Input of the StreamTracer filter.",
          "label": "Input",
          "pythonName": "Input"
        },
        "InterpolatorType": {
          "short": null,
          "long": null,
          "description": "This property determines which interpolator to use for evaluating the velocity vector field. The first is faster though the second is more robust in locating cells during streamline integration.",
          "label": "Interpolator Type",
          "pythonName": "InterpolatorType"
        },
        "MeshOverTime": {
          "short": null,
          "long": null,
          "description": "The input mesh can either be 1) different over time, or 2) static over time, or 3) a linear transformation of the first time step over time, or 4) have the same topology over time. If a value other than Different are used, then performance can be improved significantly because certain data structures, such as locators or cell links are not rebuilt for each timestep.",
          "label": "Mesh Over Time",
          "pythonName": "MeshOverTime"
        },
        "SelectInputVectors": {
          "short": null,
          "long": null,
          "description": "Specify which vector array should be used for the integration through that filter.",
          "label": "Select Input Vectors",
          "pythonName": "SelectInputVectors"
        },
        "Source": {
          "short": null,
          "long": null,
          "description": "Specify the seed dataset. Typically, from where the vector field integration should begin. Usually a point/radius or a line with a given resolution.",
          "label": "Seed Source",
          "pythonName": "SeedSource"
        },
        "StaticSeeds": {
          "short": null,
          "long": null,
          "description": "If the input seeds are not changing, then this can be set to 1 to avoid having to do a repeated grid search that would return the exact same result.",
          "label": "Static Seeds",
          "pythonName": "StaticSeeds"
        },
        "TerminalSpeed": {
          "short": null,
          "long": null,
          "description": "This property specifies the terminal speed, below which particle advection/integration is terminated.",
          "label": "Terminal Speed",
          "pythonName": "TerminalSpeed"
        },
        "TerminationTime": {
          "short": null,
          "long": null,
          "description": "Setting TerminationTime to a positive value will cause particles to terminate when the time is reached. The units of time should be consistent with the primary time variable.",
          "label": "Termination Time",
          "pythonName": "TerminationTime"
        },
        "TimestepValues": {
          "short": null,
          "long": null,
          "description": null,
          "label": "Timestep Values",
          "pythonName": "TimestepValues"
        }
      }
    },
