          "long": null,
          "description": "When set the input cell data arrays are shallow copied to the output.",
          "label": "Pass Cell Arrays",
          "pythonName": "PassCellArrays"
        },
        "PassFieldArrays": {
          "short": null,
          "long": null,
          "description": "Set whether to pass the field-data arrays from the Input i.e. the input providing the geometry to the output.",
          "label": "Pass Field Arrays",
          "pythonName": "PassFieldArrays"
        },
        "PassPartialArrays": {
          "short": null,
          "long": null,
          "description": "When dealing with composite datasets, partial arrays are common i.e. data-arrays that are not available in all of the blocks. By default, this filter only passes those point and cell data-arrays that are available in all the blocks i.e. partial arrays are removed. When PassPartialArrays is turned on, this behavior is changed to take a union of all arrays present thus partial arrays are passed as well. However, for composite dataset input, this filter still produces a non-composite output. For all those locations in a block of where a particular data array is missing, this filter uses vtkMath::Nan() for double and float arrays, and 0 for all other types of arrays i.e int, char etc.",
