          "pythonName": "Point2"
        },
        "Resolution": {
          "short": null,
          "long": null,
          "description": "This property sets the line resolution if sampling pattern is set to \"Sample Uniformly\".",
          "label": "Resolution",
          "pythonName": "Resolution"
        },
        "SamplingPattern": {
          "short": null,
          "long": null,
          "description": "\"Sample At Cell Boundaries\" gives the most accurate plots by creating probing points at the cell borders. \"Sample At Segment Centers\" provides one sample per probed cell located at the middle of the line intersecting the cell. \"Sample Uniformally\" samples uniformally along the input line.",
