    "filters/SPHDatasetInterpolator": {
      "short": null,
      "long": null,
      "description": "This filter uses SPH (smooth particle hydrodynamics) kernels to interpolate a data source onto an input structure. For example, while the data source is a set of particles, the data from these particles can be interpolated onto an input volume. Then the output (which consists of the input structure plus interpolated data) can then be visualized using classical visualization techniques such as isocontouring, slicing, heat maps and so on.",
      "selection": "This filter uses SPH (smooth particle hydrodynamics) kernels to interpolate a data source onto an input structure. For example, while the data source is a set of particles, the data from these particles can be interpolated onto an input volume. Then the output (which consists of the input structure plus interpolated data) can then be visualized using classical visualization techniques such as isocontouring, slicing, heat maps and so on.",
      "basis": "installed native documentation",
      "properties": {
        "ComputeShepardSum": {
          "short": null,
          "long": null,
          "description": "Indicate whether to compute the summation of Shepard coefficients. In the interior of a SPH point cloud, the Shephard summation value should be ~1.0. Towards the boundary, the Shepard summation is less than 1.0. If ComputeShepardSum is specified, then the output will contain an array of summed Shepard weights for each output point.",
          "label": "Compute Shepard Sum",
          "pythonName": "ComputeShepardSum"
        },
        "CutoffArray": {
          "short": null,
          "long": null,
          "description": "Specify the Cutoff array name. If not specified, then the radius at each point will be computed as cutoff factor * smoothing length at a each point.",
          "label": "Cutoff Array",
          "pythonName": "CutoffArray"
        },
        "DensityArray": {
          "short": null,
          "long": null,
          "description": "Specify the density array name. This is required in computation. If not specified the code will error out.",
          "label": "Density Array",
          "pythonName": "DensityArray"
        },
        "DerivativeArrays": {
          "short": null,
          "long": null,
          "description": "Specify the arrays whose derivative is to be taken. If the name of the array is \"derivArray\" this will produce an output array with the name \"derivArray_deriv\" (after filter execution).",
          "label": "Derivative Arrays",
          "pythonName": "DerivativeArrays"
        },
        "ExcludedArrays": {
          "short": null,
          "long": null,
          "description": "Specify arrays which are to be excluded from the interpolation process.",
          "label": "Excluded Arrays",
          "pythonName": "ExcludedArrays"
        },
        "Input": {
          "short": null,
          "long": null,
          "description": "The data source to be interpolated onto the *Source*.",
          "label": "Input",
          "pythonName": "Input"
        },
        "Kernel": {
          "short": null,
          "long": null,
          "description": null,
          "label": "Kernel",
          "pythonName": "Kernel"
        },
        "Locator": {
          "short": null,
          "long": null,
          "description": "Specify a point locator.",
          "label": "Locator",
          "pythonName": "Locator"
        },
        "MassArray": {
          "short": null,
          "long": null,
          "description": "Specify the mass array name. If not specified, then the mass at each point will be computed from the density and local (spherical) volume at a each point.",
          "label": "Mass Array",
          "pythonName": "MassArray"
        },
        "NullPointsStrategy": {
          "short": null,
          "long": null,
          "description": "Specify a strategy to use when encountering a \"null\" point during the interpolation process. Null points occur when the local neighborhood (of nearby points to interpolate from) is empty. If the strategy is set to MaskPoints, then an output array is created that marks points as being valid (=1) or null (invalid =0) (and the NullValue is set as well). If the strategy is set to NullValue, then the output data value(s) are set to the NullPoint value (specified in the output point data).",
          "label": "Null Points Strategy",
          "pythonName": "NullPointsStrategy"
        },
        "NullValue": {
          "short": null,
          "long": null,
          "description": "Specify the null point value. When a null point is encountered then all components of each null tuple are set to this value. By default the null value is set to zero.",
          "label": "Null Value",
          "pythonName": "NullValue"
        },
        "PassCellArrays": {
          "short": null,
          "long": null,
          "description": "Indicate whether to shallow copy the input cell data arrays to the output.",
          "label": "Pass Cell Arrays",
          "pythonName": "PassCellArrays"
        },
        "PassFieldArrays": {
          "short": null,
          "long": null,
          "description": "Indicate whether to shallow copy the input field data arrays to the output.",
          "label": "Pass Field Arrays",
          "pythonName": "PassFieldArrays"
        },
        "PassPointArrays": {
          "short": null,
          "long": null,
          "description": "Indicate whether to shallow copy the input point data arrays to the output.",
