          "pythonName": "PassPointArrays"
        },
        "ShepardSumArrayName": {
          "short": null,
          "long": null,
          "description": "If ComputeShepardSum is on, then an array is generated with name ShepardSumArrayName for each input point. This vtkFloatArray is placed into the output of the filter, and NullPoints have value =0.0. The default name is \"Shepard Summation\".",
          "label": "Shepard Sum Array Name",
          "pythonName": "ShepardSumArrayName"
        },
        "Source": {
          "short": null,
