    "sources/SegY Reader": {
      "short": "Reads SEG-Y data files.",
      "long": null,
      "description": "SEG-Y Reader reads SEG-Y data files. We create a Structured Grid for 2.5D SEG-Y and 3D data. If we set the StructuredGrid option to false we create a Image Data for 3D data. This saves memory and may speed-up certain algorithms, but the position and the shape of the data may not be correct. The axes for the data are: crossline, inline, depth.",
      "selection": "Reads SEG-Y data files.",
      "basis": "installed native documentation",
      "properties": {
        "FileName": {
          "short": null,
          "long": null,
          "description": "This property specifies the file name for the SEG-Y reader.",
          "label": "File Name",
          "pythonName": "FileName"
        },
        "Force2D": {
          "short": null,
          "long": null,
          "description": "Specify if we create a Structured Grid even when the data is SEG-Y 3D. Note this consumes more memory but it shows the precise location for each point and the correct shape of the data. The default value is true. If we set this option to false we create an Image Data for a SEG-Y 3D dataset. Specify if we should we force the data to be interpreted as a 2D dataset. It may be a 2D sheet through 3D space. When this is turned on we ignore the cross line and line values and instead build a 2D data by processing and connecting the traces in order from first to last. The output will be a Structured Grid.",
          "label": "Force 2D",
          "pythonName": "Force2D"
        },
        "StructuredGrid": {
          "short": null,
          "long": null,
          "description": "Specify if we create a Structured Grid even when the data is SEG-Y 3D. Note this consumes more memory but it shows the precise location for each point and the correct shape of the data. The default value is true. If we set this option to false we create an Image Data for a SEG-Y 3D dataset.",
          "label": "Structured Grid",
          "pythonName": "StructuredGrid"
        },
        "VerticalCRS": {
          "short": null,
          "long": null,
          "description": "Specify whether the vertical coordinates in the SEG-Y file are heights (positive up) or depths (positive down). By default, the vertical coordinates are treated as heights (i.e. positive up). This means that the Z-axis of the dataset goes from 0 (surface) to -ve depth (last sample). Note. As per the SEG-Y rev 2.0 specification, this information is defined in the Location Data Stanza of the Extended Textual Header. However, as of this revision, SegYReader does not support reading the extended textual header.",
          "label": "Vertical CRS",
          "pythonName": "VerticalCRS"
        },
        "XCoordByte": {
          "short": null,
          "long": null,
          "description": "Specify X and Y byte positions for custom XYCoordinateMode. By default, XCoordByte = 73, YCoordByte = 77 i.e. source xy.",
          "label": "X Coord Byte",
          "pythonName": "XCoordByte"
        },
        "XYCoordMode": {
          "short": null,
          "long": null,
          "description": "Specify whether to use source x/y coordinates or CDP coordinates or custom byte positions for data position in the SEG-Y trace header. Defaults to source x/y coordinates. As per SEG-Y rev 2.0 specification: - Source XY coordinate bytes = (73, 77) - CDP XY coordinate bytes = (181, 185)",
          "label": "XY Coord Mode",
          "pythonName": "XYCoordMode"
        },
        "YCoordByte": {
          "short": null,
          "long": null,
          "description": "Specify X and Y byte positions for custom XYCoordinateMode. By default, XCoordByte = 73, YCoordByte = 77 i.e. source xy.",
          "label": "Y Coord Byte",
          "pythonName": "YCoordByte"
        }
      }
    },
