    "filters/TemporalCache": {
      "short": "Caches data per time step.",
      "long": "Saves a copy of the data set for a fixed number of time steps.",
      "description": "The Temporal Cache can be used to save multiple copies of a data set at different time steps to prevent thrashing in the pipeline caused by downstream filters that adjust the requested time step. For example, assume that there is a downstream Temporal Interpolator filter. This filter will (usually) request two time steps from the upstream filters, which in turn (usually) causes the upstream filters to run twice, once for each time step. The next time the interpolator requests the same two time steps, they might force the upstream filters to re-evaluate the same two time steps. The Temporal Cache can keep copies of both of these time steps and provide the requested data without having to run upstream filters.",
      "selection": "Caches data per time step.",
      "basis": "installed native documentation",
      "properties": {
        "CacheSize": {
          "short": null,
          "long": null,
          "description": "The cache size determines the number of time steps that can be cached at one time. The maximum number is 10. The minimum is 2 (since it makes little sense to cache less than that).",
          "label": "Cache Size",
          "pythonName": "CacheSize"
        },
        "Input": {
          "short": null,
          "long": null,
          "description": "This property specifies the input of the Temporal Cache filter.",
