    "filters/TemporalInterpolator": {
      "short": "Interpolate between time steps.",
      "long": "Interpolate between time steps.",
      "description": "The Temporal Interpolator converts data that is defined at discrete time steps to one that is defined over a continuum of time by linearly interpolating the data's field data between two adjacent time steps. The interpolated values are a simple approximation and should not be interpreted as anything more. The Temporal Interpolator assumes that the topology between adjacent time steps does not change.",
      "selection": "Interpolate between time steps.",
      "basis": "installed native documentation",
      "properties": {
        "DiscreteTimeStepInterval": {
          "short": null,
          "long": null,
          "description": "If Discrete Time Step Interval is set to 0, then the Temporal Interpolator will provide a continuous region of time on its output. If set to anything else, then the output will define a finite set of time points on its output, each spaced by the Discrete Time Step Interval. The output will have (time range)/(discrete time step interval) time steps. (Note that the time range is defined by the time range of the data of the input filter, which may be different from other pipeline objects or the range defined in the animation inspector.) This is a useful option to use if you have a dataset with one missing time step and wish to 'fill in' the missing data with an interpolated value from the steps on either side.",
          "label": "Discrete Time Step Interval",
          "pythonName": "DiscreteTimeStepInterval"
        },
        "Input": {
          "short": null,
          "long": null,
          "description": "This property specifies the input of the Temporal Interpolator.",
          "label": "Input",
          "pythonName": "Input"
        },
        "ResampleFactor": {
          "short": null,
          "long": null,
          "description": "When ResampleFactor is a non zero positive integer, each pair of input time steps will be interpolated between with the number of steps specified. For example an input of 1,2,3,4,5 and a resample factor of 10, will produce steps 0f 1.0, 1.1, 1.2, ..., 1.9, 2.0. Irregular input steps will produce irregular output steps. Resample factor will only be used if DiscreteTimeStepInterval is zero, otherwise the DiscreteTimeStepInterval takes precedence",
          "label": "Resample Factor",
          "pythonName": "ResampleFactor"
        },
        "TimeRange": {
          "short": null,
          "long": null,
          "description": null,
          "label": "Time Range",
          "pythonName": "TimeRange"
        },
        "TimestepValues": {
          "short": null,
          "long": null,
          "description": null,
          "label": "Timestep Values",
          "pythonName": "TimestepValues"
        }
      }
    },
    "filters/ParticlePathLines": {
      "short": "Particle Pathlines",
      "long": "Creates polylines representing pathlines of animating particles",
      "description": "Particle Pathlines takes any dataset as input, it extracts the point locations of all cells over time to build up a polyline trail. The point number (index) is used as the 'key' if the points are randomly changing their respective order in the points list, then you should specify a scalar that represents the unique ID. This is intended to handle the output of a filter such as the TemporalStreamTracer.",
      "selection": "Particle Pathlines",
      "basis": "installed native documentation",
      "properties": {
        "BackwardTime": {
          "short": null,
          "long": null,
          "description": "Compute particle path lines when time goes backward.",
          "label": "Backward Time",
          "pythonName": "BackwardTime"
        },
        "IdChannelArray": {
          "short": null,
          "long": null,
          "description": "Specify the name of a scalar array which will be used to fetch the index of each point. This is necessary only if the particles change position (Id order) on each time step. The Id can be used to identify particles at each step and hence track them properly. If this array is set to \"Global or Local IDs\", the global point ids are used if they exist or the point index is otherwise.",
          "label": "Id Channel Array",
          "pythonName": "IdChannelArray"
        },
        "Input": {
          "short": null,
          "long": null,
          "description": "The input cells for which to create pathlines.",
          "label": "Input",
          "pythonName": "Input"
        },
        "KeepDeadTrails": {
          "short": null,
          "long": null,
          "description": "Keep the trails of particles that leave the domain. Use carefully as it may cause excessive memory consumption when generating many particle trails.",
          "label": "Keep Dead Trails",
          "pythonName": "KeepDeadTrails"
        },
        "MaskPoints": {
          "short": null,
          "long": null,
          "description": "Set the number of particles to track as a ratio of the input. Example: setting MaskPoints to 10 will track every 10th point.",
          "label": "Mask Points",
          "pythonName": "MaskPoints"
        },
        "MaxStepDistance": {
          "short": null,
          "long": null,
          "description": "If a particle disappears from one end of a simulation and reappears on the other side, the track left will be unrepresentative. Set a MaxStepDistance{x,y,z} which acts as a threshold above which if a step occurs larger than the value (for the dimension), the track will be dropped and restarted after the step. That is, the part before the wrap around will be dropped and the newer part kept.",
          "label": "Max Step Distance",
          "pythonName": "MaxStepDistance"
        },
        "MaxTrackLength": {
          "short": null,
          "long": null,
          "description": "If the particles being traced animate for a long time, the trails or traces will become long and stringy. Setting the MaxTraceTimeLength will limit how much of the trace is displayed. Tracks longer then the Max will disappear and the trace will appear like a snake of fixed length which progresses as the particle moves. This length is given with respect to timesteps.",
          "label": "Max Track Length",
          "pythonName": "MaxTrackLength"
        },
        "Selection": {
          "short": null,
          "long": null,
          "description": "Set a second input, which is a selection. Particles with the same Id in the selection as the primary input will be chosen for pathlines. Note that you must have the same IdChannelArray in the selection as the input.",
          "label": "Selection",
          "pythonName": "Selection"
        }
      }
    },
    "filters/TemporalShiftScale": {
      "short": "Shift and scale time values.",
      "long": "Shift and scale time values.",
      "description": "The Temporal Shift Scale filter linearly transforms the time values of a pipeline object by applying a shift and then scale. Given a data at time t on the input, it will be transformed to time t*Shift + Scale on the output. Inversely, if this filter has a request for time t, it will request time (t-Shift)/Scale on its input.",
      "selection": "Shift and scale time values.",
      "basis": "installed native documentation",
      "properties": {
        "Input": {
          "short": null,
          "long": null,
          "description": "The input to the Temporal Shift Scale filter.",
          "label": "Input",
          "pythonName": "Input"
        },
        "MaximumNumberOfPeriods": {
          "short": null,
          "long": null,
          "description": "If Periodic time is enabled, this controls how many time periods time is reported for. A filter cannot output an infinite number of time steps and therefore a finite number of periods is generated when reporting time.",
          "label": "Maximum Number Of Periods",
          "pythonName": "MaximumNumberOfPeriods"
        },
        "Periodic": {
          "short": null,
          "long": null,
          "description": "If Periodic is true, requests for time will be wrapped around so that the source appears to be a periodic time source. If data exists for times {0,N-1}, setting periodic to true will cause time 0 to be produced when time N, 2N, 2N etc is requested. This effectively gives the source the ability to generate time data indefinitely in a loop. When combined with Shift/Scale, the time becomes periodic in the shifted and scaled time frame of reference. Note: Since the input time may not start at zero, the wrapping of time from the end of one period to the start of the next, will subtract the initial time - a source with T{5..6} repeated periodically will have output time {5..6..7..8} etc.",
          "label": "Periodic",
          "pythonName": "Periodic"
        },
        "PeriodicEndCorrection": {
          "short": null,
          "long": null,
          "description": "If Periodic time is enabled, this flag determines if the last time step is the same as the first. If PeriodicEndCorrection is true, then it is assumed that the input data goes from 0-1 (or whatever scaled/shifted actual time) and time 1 is the same as time 0 so that steps will be 0,1,2,3...N,1,2,3...N,1,2,3 where step N is the same as 0 and step 0 is not repeated. When this flag is false the data is assumed to be literal and output is of the form 0,1,2,3...N,0,1,2,3... By default this flag is ON",
          "label": "Periodic End Correction",
          "pythonName": "PeriodicEndCorrection"
        },
        "PostShift": {
          "short": null,
          "long": null,
          "description": "The amount of time the input is shifted.",
          "label": "Post Shift",
          "pythonName": "PostShift"
        },
        "PreShift": {
          "short": null,
          "long": null,
          "description": "Apply a translation to the data before scaling. To convert T{5,100} to T{0,1} use Preshift=-5, Scale=1/95, PostShift=0 To convert T{5,105} to T{5,10} use Preshift=-5, Scale=5/100, PostShift=5",
          "label": "Pre Shift",
          "pythonName": "PreShift"
        },
        "Scale": {
          "short": null,
          "long": null,
          "description": "The factor by which the input time is scaled.",
          "label": "Scale",
          "pythonName": "Scale"
        },
        "TimestepValues": {
          "short": null,
          "long": null,
          "description": null,
          "label": "Timestep Values",
          "pythonName": "TimestepValues"
        }
      }
    },
    "filters/TemporalSmoothing": {
      "short": "Smooths a temporal input over a sliding temporal window.",
      "long": "This filter smooths a temporal input's point and cell data by computing an average over a temporal window.",
      "description": "Given an input that changes over time, Temporal Smoothing will provide an average of each point and cell data values over a temporal window centered on a requested time step. Because of this, the input's topology is assumed to not change over time, and so the number and order of its points and cells should stay the same. In order to provide comparable results for different time steps, the temporal window must be the same size. To enforce this the filter clips its input available time steps to allow the full window size to fit. If an out-of-bound time step is requested, the filter will use the closest available time step. Note that updating this filter will trigger upstream updates for each time steps of the window, which could be expensive.",
      "selection": "Smooths a temporal input over a sliding temporal window.",
      "basis": "installed native documentation",
      "properties": {
        "Input": {
          "short": null,
          "long": null,
          "description": "Set the input to the Temporal Smoothing filter.",
          "label": "Input",
          "pythonName": "Input"
        },
        "TemporalWindowHalfWidth": {
          "short": null,
          "long": null,
          "description": "Set the temporal window half width. When requesting a time step, the associated data will be smoothed using this number of time steps before and after it. The resulting window's width is (halfwidth*2)+1 time steps. This property also influences the number of timesteps produced by the filter to exclude time steps where the full window cannot be applied.",
          "label": "Temporal Window Half Width",
          "pythonName": "TemporalWindowHalfWidth"
        },
        "TimestepValues": {
          "short": null,
          "long": null,
          "description": null,
          "label": "Timestep Values",
          "pythonName": "TimestepValues"
        }
      }
    },
