    "filters/Threshold": {
      "short": "Extract cells that satisfy a threshold criterion.",
      "long": "This filter extracts cells that have point or cell scalars in the specified range.",
      "description": "The Threshold filter extracts the portions of the input dataset whose scalars lie within the specified range. This filter operates on either point-centered or cell-centered data. It operates on any type of dataset and produces unstructured grid output. The scalar array from which to threshold the data can be selected in the 'Scalars' menu. For a multi-components array, 'Selected Component' menu allows you to select a specific component or magnitude if using the 'Selected' component mode. You can also choose 'All' or 'Any' that will keep data if either all components or at least one satisfies the threshold. Note that multi-components arrays are not available with Hyper Tree Grid inputs. The 'Lower Threshold' and 'Upper Threshold' sliders determine the range of the scalars to retain in the output. The threshold method can be selected from the 'Threshold Method' menu. The 'All Scalars' option only applies to Point Data. When this option is on, a cell will only be passed to the output if the scalar values of all of its points lie within the chosen range. When off, a cell will be added to the output if the specified scalar value for any of its points is within the chosen range.",
      "selection": "Extract cells that satisfy a threshold criterion.",
      "basis": "installed native documentation",
      "properties": {
        "AllScalars": {
          "short": null,
          "long": null,
          "description": "If the value of this property is 1, then a cell is only included in the output if the value of the selected array for all its points is within the threshold. This is only relevant when thresholding by a point-centered array.",
          "label": "All Scalars",
          "pythonName": "AllScalars"
        },
        "ComponentMode": {
          "short": null,
          "long": null,
          "description": "This property specifies how multi-component arrays are handled. 'Selected' will use the 'Selected Component' property. 'All' will pass if all components satisfy the rule. 'Any' will pass if any component satisfies the rule.",
          "label": "Component Mode",
          "pythonName": "ComponentMode"
        },
        "Input": {
          "short": null,
          "long": null,
          "description": "This property specifies the input to the Threshold filter.",
          "label": "Input",
          "pythonName": "Input"
        },
        "Invert": {
          "short": null,
          "long": null,
          "description": "Invert the threshold results. That is, cells that would have been in the output with this option off are excluded, while cells that would have been excluded from the output are included.",
          "label": "Invert",
          "pythonName": "Invert"
        },
        "LowerThreshold": {
          "short": null,
          "long": null,
          "description": "The value of this property specifies the lower bound of the thresholding operation.",
          "label": "Lower Threshold",
          "pythonName": "LowerThreshold"
        },
        "MemoryStrategy": {
          "short": null,
          "long": null,
          "description": "Select how to construct the result in memory: - MaskInput (default): shallow copy the input and mask all cells being thresholded - Regenerate Trees And Index Fields: generate a new tree structure but use indexed arrays on the input for cell data - New HyperTreeGrid: construct a new HyperTreeGrid from scratch representing the minimal threshold of the input",
          "label": "Memory Strategy",
          "pythonName": "MemoryStrategy"
        },
        "SelectInputScalars": {
          "short": null,
          "long": null,
          "description": "The value of this property contains the name of the array from which to perform thresholding. Be aware that HTG does not support multi-component arrays.",
          "label": "Scalars",
          "pythonName": "Scalars"
        },
        "SelectedComponent": {
          "short": null,
          "long": null,
          "description": "This property specifies which component of the array needs to satisfy the rule.",
          "label": "Selected Component",
          "pythonName": "SelectedComponent"
        },
        "ThresholdMethod": {
          "short": null,
          "long": null,
          "description": "This property indicates the threshold method.",
          "label": "Threshold Method",
          "pythonName": "ThresholdMethod"
        },
        "UpperThreshold": {
          "short": null,
          "long": null,
          "description": "The value of this property specifies the upper bound of the thresholding operation.",
          "label": "Upper Threshold",
          "pythonName": "UpperThreshold"
        },
        "UseContinuousCellRange": {
          "short": null,
          "long": null,
          "description": "If off, the vertex scalars are treated as a discrete set. If on, they are treated as a continuous interval over the minimum and maximum. One important \"on\" use case: When setting lower and upper threshold equal to some value and turning AllScalars off, the results are cells containing the isosurface for that value. WARNING: Whether on or off, for higher order input, the filter will not give accurate results.",
          "label": "Use Continuous Cell Range",
          "pythonName": "UseContinuousCellRange"
        }
      }
    },
